function validate([mat, threshold]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 300) return 'mat needs 1 to 300 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 300) return 'Each row needs 1 to 300 values.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row of mat must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each cell is a whole number from 0 to 10^4.';
  }
  if (!Number.isInteger(threshold) || threshold < 0 || threshold > 100000) return 'threshold is a whole number from 0 to 10^5.';
  return null;
}

