function maxSideLength(mat, threshold) {
  const m = mat.length;
  const n = mat[0].length;
  let answer = 0;
  for (let top = 0; top < m; top++) {
    for (let lft = 0; lft < n; lft++) {
      for (let k = 1; top + k <= m && lft + k <= n; k++) {
        let total = 0;
        for (let r = top; r < top + k; r++) for (let c = lft; c < lft + k; c++) total += mat[r][c];
        if (total <= threshold && k > answer) answer = k;
      }
    }
  }
  return answer;
}

