function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const m = large ? int(60, 100) : int(1, 5);
  const n = large ? int(60, 100) : int(1, 5);
  const top = large ? [5, 50, 500, 10000][int(0, 3)] : [0, 2, 9, 30][int(0, 3)];
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, top)));
  let threshold;
  const roll = rand();
  if (large) {
    if (roll < 0.15) threshold = 100000;
    else if (roll < 0.3) threshold = int(0, top);
    else threshold = int(0, Math.min(100000, top * 400));
  } else {
    if (roll < 0.15) threshold = 0;
    else threshold = int(0, Math.min(100000, Math.max(1, top) * 12));
  }
  return [mat, threshold];
}
